const fs = require('fs');
const buf = fs.readFileSync('/workspace/world.db');
const text = buf.toString('latin1');

// Wider extract to get numeric fields
const idx = text.indexOf('PROD-3E35A7');
// Go back further for possible leading numeric fields
const start = idx - 30;
const nextProd = text.indexOf('PROD-', idx + 11);
const region = buf.slice(start, nextProd + 20);

// Print individual bytes to decode SQLite record format
const bytes = [];
for (let i = 0; i < region.length; i++) {
  bytes.push(region[i]);
}

// Just output byte values from idx-30 to see numeric field encoding
console.log('Bytes before and within PROD-3E35A7 record:');
for (let i = 0; i < Math.min(200, region.length); i++) {
  const b = region[i];
  const ch = (b >= 32 && b <= 126) ? String.fromCharCode(b) : '.';
  if (i % 20 === 0) process.stdout.write('\n' + String(i).padStart(4) + ': ');
  process.stdout.write(String(b).padStart(4) + '(' + ch + ') ');
}
console.log();
"

