const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

// Apply SAVE20OFF promo to the cart
const cart = db.prepare(\"SELECT * FROM carts WHERE cart_id = 'CART-user_03dd1ad7'\").get();

const newDiscountAmount = cart.discount_amount + 20;
const newTotal = cart.subtotal - newDiscountAmount - cart.loyalty_discount + cart.gift_wrap_fee + cart.shipping_cost;
const appliedPromos = JSON.parse(cart.applied_promo_codes_json);
