  UPDATE carts 
  SET discount_amount = ?, 
      total = ?, 
      applied_promo_codes_json = ?
  WHERE cart_id = ?
\`).run(newDiscountAmount, newTotal, JSON.stringify(appliedPromos), 'CART-user_03dd1ad7');

// Verify the update
const updated = db.prepare(\"SELECT * FROM carts WHERE cart_id = 'CART-user_03dd1ad7'\").get();
console.log(JSON.stringify(updated, null, 2));
